import{_ as t,o as e,c as d,a2 as l}from"./chunks/framework.BUwdTBzS.js";const u=JSON.parse('{"title":"按需-更新日志编写规范","description":"更新日志（changelog）条目的编写规范（概括式、同源优先合并为一条、只留 API 锚点不写症状白描、不写实现细节与常量数值、引用的组件与属性须核实）。撰写、修订或回改历史条目时加载。","frontmatter":{"title":"按需-更新日志编写规范","description":"更新日志（changelog）条目的编写规范（概括式、同源优先合并为一条、只留 API 锚点不写症状白描、不写实现细节与常量数值、引用的组件与属性须核实）。撰写、修订或回改历史条目时加载。"},"headers":[],"relativePath":"rules/按需-更新日志编写规范.md","filePath":"rules/按需-更新日志编写规范.md","lastUpdated":null}'),r={name:"rules/按需-更新日志编写规范.md"};function i(c,o,n,s,a,g){return e(),d("div",null,[...o[0]||(o[0]=[l('<blockquote><p>📄 本页由源文件 <code>rules/按需-更新日志编写规范.mdc</code> 自动投影生成（单一权威源）。请勿直接编辑本页。</p></blockquote><h1 id="按需-更新日志编写规范" tabindex="-1">按需-更新日志编写规范 <a class="header-anchor" href="#按需-更新日志编写规范" aria-label="Permalink to &quot;按需-更新日志编写规范&quot;">​</a></h1><blockquote><p>触发时机：撰写或修订项目 <code>changelog.md</code>（或同类版本更新说明）时。 核心：日志面向<strong>使用者</strong>，只回答「哪个组件、发生了什么、我要不要动代码」。</p></blockquote><hr><h2 id="_1-描述方式-概括式" tabindex="-1">1. 描述方式：概括式 <a class="header-anchor" href="#_1-描述方式-概括式" aria-label="Permalink to &quot;1. 描述方式：概括式&quot;">​</a></h2><ul><li><strong>一条一句话</strong>，只写「改了什么 + 影响」；根因、算法、实现手段不写进日志</li><li>「一句话」指<strong>概括方式</strong>（不展开根因与实现细节），不是「一句里塞多件事」</li><li>❌ <code>定位尺寸改用 offsetWidth / offsetHeight，因为 transform 会让 getBoundingClientRect 返回缩放后的视觉尺寸</code></li><li>✅ <code>修复缩放动画期间位置错位</code></li><li>表述落到<strong>结果层</strong>：需要读者理解内部机制才读懂的写法必须改写（❌ <code>坏键不再中断回调，其余组件主题色恢复更新</code> → ✅ <code>坏键改为忽略并告警</code>）</li><li><strong>不复述未变化的取值</strong>：默认值 / 默认行为没变时，不写「未传入时仍跟随 X（X + 24）」这类取值细节，只写「修复 X 属性不生效的问题」</li><li>根因、取舍与实现细节归 commit message / PR 描述</li><li><strong>边界</strong>：「实现细节」指内部构建 / 脚本 / 测试 / 重构等使用者不可感知的改动；<strong><code>docs/</code> 与 <code>development/</code> 的内容更新不属于此列，必须入日志</strong>（写法见 §2、§3）</li></ul><h3 id="_1-1-细节颗粒-留锚点-删症状" tabindex="-1">1.1 细节颗粒：留锚点，删症状 <a class="header-anchor" href="#_1-1-细节颗粒-留锚点-删症状" aria-label="Permalink to &quot;1.1 细节颗粒：留锚点，删症状&quot;">​</a></h3><ul><li><strong>必须保留检索锚点</strong>：属性 / 事件 / 方法 / 插槽 / <code>CSS</code> 变量名（如 <code>start()</code>、<code>interval</code>、<code>itemStyle</code>）——读者靠它们在自研代码里对号，删了就无法判断是否波及自己</li><li><strong>症状不复述</strong>：同一问题能观察到的多个症状不逐条列，最多留<strong>一句</strong>最有辨识度的 <ul><li>❌ <code>重复调用 start() 会叠加（越滚越快、stop() 停不下来），KeepAlive 失活后仍在推进、返回时已跳到其他条目，卸载后残留定时器</code></li><li>✅ <code>垂直滚动的启停：start() 重复调用与卸载后调用不再叠加滚动、KeepAlive 失活即暂停</code></li></ul></li><li>症状白描属「读者本就知道的表象」，锚点与影响属「读者尚未掌握的信息」，篇幅优先给后者</li></ul><h2 id="_2-合并同源、拆开异源" tabindex="-1">2. 合并同源、拆开异源 <a class="header-anchor" href="#_2-合并同源、拆开异源" aria-label="Permalink to &quot;2. 合并同源、拆开异源&quot;">​</a></h2><ul><li><strong>判定顺序：先合并，再拆分</strong> —— 同一组件、同一工具函数族、同一能力主题的多个改动<strong>默认合并为一条</strong>（主句概括 + 括号 / 分句承接具体结果）；仅当合并后一条里仍有<strong>不相关主题</strong>时，才拆开</li><li><strong>条目数 ≈ 主题数，不是症状数</strong>：同一组件的多个修复落在同一主题（滚动行为 / 表单校验 / 样式属性 / 主题变量…）就只写一条；<strong>补丁版本只动一个组件时，正常是 1 条（+ 兜底条）</strong></li><li>❌ 同组件拆两条：<code>修复 ConfigProvider 运行期增删组件键不生效</code> + <code>修复 ConfigProvider 对非本库组件键的处理</code>（读者要把同一个主语读两遍）</li><li>✅ <code>修复 [全局化配置 ConfigProvider](/guide/components/config-provider.html) 组件级主题：运行期增删组件键即时生效（新增覆盖生效、移除覆盖回退 common），theme 中的非本库组件键改为忽略并告警</code></li><li><strong>「不相关主题」的判定</strong>：读者是否需要<strong>做出不同动作 / 关注不同 API 面</strong>（如行为修复与破坏性 API 变更并存）——「行为 vs 样式」「代码 vs 文档」这类内部分类不算不相关，<strong>不得据此拆条</strong></li><li>❌ 一条里混入多个<strong>不相关主题</strong>（如「新增属性 + 构建产物调整」）—— 读者无法判断其中哪句与自己相关</li><li><strong>同一组件名 / 主题不应在相邻多条里重复出现</strong>，出现即说明该合并</li><li>合并的对象是「同源改动」，不是「为控制条数而压缩」；确实不同源就拆开，宁可条数多也不要堆叠</li><li><strong>同源文档更新并入该条</strong>（不另起「更新文档」条），但仍须按 §3 写明受众与主题</li><li>收尾条目（如「组件库及文档代码优化」）按维护者习惯保留，不擅自删除或改写 —— 但<strong>不是省略文档更新</strong>：文档更新须写明「<strong>哪类受众文档</strong>（使用者文档 <code>docs/</code> / <code>README</code>、贡献者文档 <code>development/</code> / <code>CONTRIBUTING</code>）+ <strong>变了什么主题</strong>」；<strong>不写具体文件路径</strong>，排版 / 格式类调整不展开细节（列数、格式名等）；受众不同的文档更新各自成条，禁止「优化文档」这类一句打包写法</li></ul><h2 id="_3-保留必要信息-不得过度概括" tabindex="-1">3. 保留必要信息（不得过度概括） <a class="header-anchor" href="#_3-保留必要信息-不得过度概括" aria-label="Permalink to &quot;3. 保留必要信息（不得过度概括）&quot;">​</a></h2><p>以下必须写清，压缩到看不出影响即不合格：</p><table tabindex="0"><thead><tr><th>场景</th><th>要求</th></tr></thead><tbody><tr><td>破坏性变更</td><td><strong>不标注</strong>「破坏性变更」字样或用 <code>⚠️</code> 等强调标记，按动词正常起句，写明「移除了什么 / 改用什么」</td></tr><tr><td>默认值变化</td><td>写明旧值 → 新值（<strong>未变化时不复述默认值</strong>）</td></tr><tr><td>需用户改代码</td><td>写明替代写法</td></tr><tr><td>影响面 / 触发条件</td><td>写明「什么配置下会踩到」+「同参数下表现是否变化」：<code>interval</code> 改为纯停留时长后，同一取值整体滚动变慢，需调速的读者据此下调；<code>itemStyle</code> 的 <code>maxWidth</code> 仅开启 <code>ellipsis</code> 时失效，不能写成「垂直滚动时失效」</td></tr><tr><td>文档更新</td><td>按受众写「使用者文档 / 贡献者文档 / <code>README</code>」+ 变了什么主题；不写文件路径与排版细节，不写「优化文档」这类打包表述</td></tr><tr><td>与某修复同源的文档更新</td><td>并入该修复条（不另起条），仍写明受众 + 主题</td></tr></tbody></table><h2 id="_4-格式约定" tabindex="-1">4. 格式约定 <a class="header-anchor" href="#_4-格式约定" aria-label="Permalink to &quot;4. 格式约定&quot;">​</a></h2><ul><li>每条以动词开头：<code>新增</code> / <code>优化</code> / <code>增强</code> / <code>修复</code> / <code>重构</code></li><li><strong>不使用 <code>⚠️</code> 等强调标记</strong>：破坏性变更 / 默认值变化 / API 移除同样以动词正常起句，靠正文里的「原 X → 现 Y」说清影响，不加前缀、不加粗警示</li><li>组件与工具函数名用 Markdown 链接指向文档，如 <code>[文字提示 Tooltip](/guide/components/tooltip.html)</code></li><li>属性名、API、全局对象等用行内代码包裹</li><li><strong>条目数不设上限</strong>：由改动量自然决定 —— 架构重构、批量破坏性变更的大版本条目自然多，小版本自然少</li><li><strong>不为凑数拆分</strong>（一件事写成多条），<strong>也不为控数堆叠或删减信息</strong>（多件事挤进一条、砍掉必要语义）</li><li>每条长度以「一句话可读」为准：合并后的具体结果用括号 / 分句承接，可用分号把「启停 / 节奏 / 样式」等子话题分组</li><li><strong>「并列项 ≤ 2」只是排版建议</strong>（超了先概括或分组），<strong>不作拆条依据</strong>；是否拆条只按 §2 的主题判定</li></ul><h2 id="_5-版本与历史" tabindex="-1">5. 版本与历史 <a class="header-anchor" href="#_5-版本与历史" aria-label="Permalink to &quot;5. 版本与历史&quot;">​</a></h2><ul><li>已发布版本的历史条目<strong>默认不回改</strong>，用户明确要求时才回改</li><li>新版本严格按本规范撰写，不因历史风格而妥协</li><li>回改历史条目只做两件事：删实现细节（见 §6）、去掉 <code>⚠️</code> /「破坏性变更」标记并改为动词起句；<strong>兜底条目原样保留</strong>（见 §6 末条）</li><li>回改不改写事实、不合并版本、不动 <code>VersionDateTag</code>、链接与版本号；改完自查「版本数不变、无空版本块」</li></ul><h2 id="_6-实现细节一律不写" tabindex="-1">6. 实现细节一律不写 <a class="header-anchor" href="#_6-实现细节一律不写" aria-label="Permalink to &quot;6. 实现细节一律不写&quot;">​</a></h2><p>日志只保留「组件 / 能力 + 可感知结果」，以下内容属于实现细节，出现即删：</p><table tabindex="0"><thead><tr><th>类别</th><th>❌ 不写</th><th>✅ 只写结果</th></tr></thead><tbody><tr><td>常量数值</td><td><code>动效时长由 0.3s 收敛为 0.2s</code>、<code>基线压低 1px</code>、<code>默认色 15% 黑</code></td><td><code>动效时长缩短</code>、<code>基线压低</code>、<code>默认色随模式反转</code></td></tr><tr><td>缓动 / 曲线 / 关键帧</td><td><code>两段同为 ease-out-circ</code>、<code>进场与离场各用一条缓动曲线</code></td><td>不写（除非本身就是可配置的 API）</td></tr><tr><td>内部 API 与算法</td><td><code>requestAnimationFrame 合并同帧重算</code>、<code>按 placement 分组管理数据与定时器</code>、<code>模块级统一捕获点击位置</code></td><td>只写用户看到的变化</td></tr><tr><td>内部术语</td><td><code>并存两条滚动节拍</code>、<code>与 Swiper 的 interval 口径一致</code></td><td>换成使用者视角：<code>越滚越快、stop() 停不下来</code>、不写对标</td></tr><tr><td>构造与结构</td><td><code>svg 改为声明式渲染</code>、<code>不再在 setup 阶段访问全局对象</code>、<code>改用交互式演示</code></td><td><code>体积减小</code>、<code>修复 SSR 渲染报错</code>、<code>补充可运行示例</code></td></tr><tr><td>依赖与构建</td><td><code>移除 @vuepic/vue-datepicker</code>、<code>新增第三方样式单一数据源</code>、<code>优化 vite 构建配置</code></td><td><code>移除第三方依赖</code>；纯构建 / 脚本 / 测试改动不进日志</td></tr></tbody></table><ul><li><strong>删除优于模糊化</strong>：拿不准怎么概括就整句删掉，不要换成「优化了性能 / 调整了逻辑」这类更空的表述</li><li><strong>例外</strong>：常量本身就是公开 API（属性默认值、枚举取值、<code>CSS</code> 变量名）时按 §3 写清旧值 → 新值</li><li><strong>兜底条目不在回改范围</strong>：<code>组件库及文档代码优化</code>、<code>优化 X 组件代码 / 组件实现</code>、<code>组件库脚本优化</code> 等是作者刻意保留的版本记录 —— §2 的「兜底条目不写」只约束新版本，历史条目里已有的原样保留</li></ul><h2 id="_7-事实核实" tabindex="-1">7. 事实核实 <a class="header-anchor" href="#_7-事实核实" aria-label="Permalink to &quot;7. 事实核实&quot;">​</a></h2><ul><li>日志里出现的<strong>组件名 / 属性名 / 事件名 / 文档链接</strong>必须在源码或 <code>docs/</code> 里核实存在，不靠印象</li><li><strong>跨组件对标</strong>只在两边 API 名真正对得上时才写：❌ <code>与 [轮播图 Swiper] 的 interval 口径一致</code>（Swiper 实为 <code>delay</code> / <code>speed</code>）→ ✅ 只写「停留与过渡分开计时」，不写对标</li><li>默认值、旧值 → 新值回源码确认（<code>Props</code> 接口 / <code>withDefaults</code> / 组件 <code>docs</code> 属性表），不凭记忆写数字或属性名</li><li>修复类条目落笔前先回看 diff，确认「修的范围」与「写的范围」一致（如仅某分支失效，不得写成整体失效）</li></ul><h2 id="_8-自检清单" tabindex="-1">8. 自检清单 <a class="header-anchor" href="#_8-自检清单" aria-label="Permalink to &quot;8. 自检清单&quot;">​</a></h2><ul><li>[ ] 每条能否一句话说清「改了什么 + 影响」？</li><li>[ ] 同组件 / 同工具函数族 / 同能力主题的改动是否已<strong>优先合并</strong>为一条？（先合并，再拆分）</li><li>[ ] <strong>条目数是按「主题数」还是「症状数」定的</strong>？同组件的同类修复是否还在分条？（单组件补丁版本通常 1 条）</li><li>[ ] 同一组件名 / 主题是否在相邻多条里重复出现？出现即合并</li><li>[ ] 是否存在「一条堆叠多个不相关主题」的情况？应拆为多条</li><li>[ ] 是否残留<strong>症状白描</strong>？该留的 API / 属性锚点是否齐全？</li><li>[ ] 破坏性变更、默认值变化是否写明替代用法？未变化的默认值是否已删去复述？</li><li>[ ] 是否写明<strong>触发条件</strong>与对既有取值的影响（同参数下表现是否变化）？</li><li>[ ] 是否残留 <code>⚠️</code> 或「破坏性变更」前缀等强调标记？（一律不写）</li><li>[ ] 是否残留根因、算法、内部函数名、内部术语，或需要读者理解内部机制才读懂的表述？</li><li>[ ] 是否残留具体常量数值（时长 / 像素 / 百分比）、缓动曲线、内部 API 或构建手段？（见 §6）</li><li>[ ] <strong>引用的组件 / 属性 / 链接是否核实存在</strong>？跨组件对标的两边 API 名对得上吗？</li><li>[ ] 回改历史时是否只删实现细节（兜底条目原样保留）、版本数与版本块结构未受损？</li><li>[ ] 文档更新是否按受众写明「哪类文档 + 变了什么主题」？（不写文件路径与排版细节；同源更新已并入该条）</li><li>[ ] 是否擅自删掉了维护者惯用的收尾条目（如「组件库及文档代码优化」）？应原样保留</li><li>[ ] 是否为了控制条数而删减或模糊了必要信息？（条目数不是压缩目标）</li></ul>',25)])])}const _=t(r,[["render",i]]);export{u as __pageData,_ as default};
